(4663905, 673312, 44877, '<td valign="top">That''s cute.</td>', 'That''s cute.', '2008-04-28 22:03:37.000000', NULL, 1),
(4663907, 673222, 44877, '<td valign="top">Spectacularly wonderful. Love the BW, the composition and the deadpan expressions of your models. It''s fantastic.</td>', 'Spectacularly wonderful. Love the BW, the composition and the deadpan expressions of your models. It''s fantastic.', '2008-04-28 22:04:42.000000', NULL, 1),
(4663917, 673473, 44877, '<td valign="top">How do they know which is rock, paper or scissors?</td>', 'How do they know which is rock, paper or scissors?', '2008-04-28 22:10:32.000000', NULL, 1),
