(4666972, 673311, 80821, '<td valign="top">Lovely work picking out the hair, nice b&amp;w convertion as well. The stick seems burnt out though which would be my only complaint, short of that, good picture.</td>', 'Lovely work picking out the hair, nice b&w convertion as well. The stick seems burnt out though which would be my only complaint, short of that, good picture.', '2008-04-30 06:42:23.000000', NULL, 1),
(4667007, 672704, 89076, '<td valign="top">As an Ice hockey fan <b>I love </b>this photograph. I love the idea of the lighting techniques to create the shadows and make it have an impact. Looks mysterious, great photograph :)</td>', 'As an Ice hockey fan I love this photograph. I love the idea of the lighting techniques to create the shadows and make it have an impact. Looks mysterious, great photograph :)', '2008-04-30 07:30:55.000000', NULL, 1),
(4667314, 673552, 71608, '<td valign="top">It''s a great capture, I also would love to see it in black and white!</td>', 'It''s a great capture, I also would love to see it in black and white!', '2008-04-30 10:04:00.000000', NULL, 1),
(4667317, 673011, 71608, '<td valign="top">Haha, the guy at the back on the bike laughing is quite funny! A great capture, such concentration...</td>', 'Haha, the guy at the back on the bike laughing is quite funny! A great capture, such concentration...', '2008-04-30 10:05:34.000000', NULL, 1),
