(4668205, 673600, 67363, '<td valign="top">reat job</td>', 'reat job', '2008-04-30 15:41:54.000000', NULL, 1),
(4668211, 671894, 67363, '<td valign="top">Great action. I feel like I am right there.</td>', 'Great action. I feel like I am right there.', '2008-04-30 15:42:48.000000', NULL, 1),
(4668218, 673149, 67363, '<td valign="top">very clever</td>', 'very clever', '2008-04-30 15:44:31.000000', NULL, 1),
(4668251, 672395, 67363, '<td valign="top">beautiful photo but would have benefited by being a bit lighter.</td>', 'beautiful photo but would have benefited by being a bit lighter.', '2008-04-30 15:54:50.000000', NULL, 1),
(4668538, 673591, 30982, '<td valign="top">Wonderful!  Love this!  Bumping this up.  This truly embodies the spirit of the challenge best of all the entries and makes me smile, too.</td>', 'Wonderful!  Love this!  Bumping this up.  This truly embodies the spirit of the challenge best of all the entries and makes me smile, too.', '2008-04-30 17:21:16.000000', NULL, 1),
(4668563, 672704, 63244, '<td valign="top">GO STARS! :P  This is a great shot.  The shadowing adds such mood to the portrait and the negative space to the left works well.  You might be able to crop just a touch of the neg space off and still get a very impactful photo. Nice job!</td>', 'GO STARS! :P  This is a great shot.  The shadowing adds such mood to the portrait and the negative space to the left works well.  You might be able to crop just a touch of the neg space off and still get a very impactful photo. Nice job!', '2008-04-30 17:28:08.000000', NULL, 1),
(4668574, 673483, 63244, '<td valign="top">This is a nice shot.  The difficulty in b/w &amp; sepia toned shots is that it can enhance the detail too much sometimes and other times cause a photograph to become flat.  There are areas that need more Omph here, but bumping up the contrast would make is scream in other areas. I still like this.  Great choice in costuming.</td>', 'This is a nice shot.  The difficulty in b/w & sepia toned shots is that it can enhance the detail too much sometimes and other times cause a photograph to become flat.  There are areas that need more Omph here, but bumping up the contrast would make is scream in other areas. I still like this.  Great choice in costuming.', '2008-04-30 17:30:58.000000', NULL, 1),
(4668583, 673019, 63244, '<td valign="top">Great detail in this shot and your colors are perfect! (On my monitor.)</td>', 'Great detail in this shot and your colors are perfect! (On my monitor.)', '2008-04-30 17:34:05.000000', NULL, 1),
(4668593, 673596, 63244, '<td valign="top">I like the idea and I like the lighting, but this is very hard to look at. Lots going on in a not so interesting way. :(  (Hope they have insurance!)</td>', 'I like the idea and I like the lighting, but this is very hard to look at. Lots going on in a not so interesting way. :(  (Hope they have insurance!)', '2008-04-30 17:36:32.000000', NULL, 1),
(4668598, 673592, 63244, '<td valign="top">The leading lines and the framing work well in this shot.  Looks a touch bright on my monitor.</td>', 'The leading lines and the framing work well in this shot.  Looks a touch bright on my monitor.', '2008-04-30 17:37:31.000000', NULL, 1),
(4668601, 673544, 63244, '<td valign="top">Had to hunt for the focus spot. :)</td>', 'Had to hunt for the focus spot. :)', '2008-04-30 17:38:20.000000', NULL, 1),
