(4668854, 673444, 91295, '<td valign="top">Hehehe...that is funny.</td>', 'Hehehe...that is funny.', '2008-04-30 18:34:06.000000', NULL, 1),
(4668875, 673401, 91295, '<td valign="top">I like this image (the colors, saturation), but the blown out background is very distracting</td>', 'I like this image (the colors, saturation), but the blown out background is very distracting', '2008-04-30 18:39:27.000000', NULL, 1),
