(4676320, 673310, 76335, '<td valign="top">Beautiful primaries here. Nice DOF too.</td>', 'Beautiful primaries here. Nice DOF too.', '2008-05-03 00:48:39.000000', NULL, 1),
(4676321, 672395, 76335, '<td valign="top">Nice capture and low-key processing.</td>', 'Nice capture and low-key processing.', '2008-05-03 00:48:43.000000', NULL, 1),
(4676322, 671998, 76335, '<td valign="top">Neat idea. I think if the cards were stacked differently to show more of the surface, it might have worked better.</td>', 'Neat idea. I think if the cards were stacked differently to show more of the surface, it might have worked better.', '2008-05-03 00:48:58.000000', NULL, 1),
(4676323, 673597, 76335, '<td valign="top">That''s just evil. Nicely composed, lit and processed.</td>', 'That''s just evil. Nicely composed, lit and processed.', '2008-05-03 00:49:01.000000', NULL, 1),
(4676324, 673552, 76335, '<td valign="top">Great title and nicely composed. Too bad you couldn''t get better lighting and focus on this.</td>', 'Great title and nicely composed. Too bad you couldn''t get better lighting and focus on this.', '2008-05-03 00:49:15.000000', NULL, 1),
(4676326, 673410, 76335, '<td valign="top">The camera is the real hero here. Excellent colors and sharp focus.</td>', 'The camera is the real hero here. Excellent colors and sharp focus.', '2008-05-03 00:49:19.000000', NULL, 1),
(4676327, 673482, 76335, '<td valign="top">I hated this game -- it made me a nervous wreck. Or maybe because I was a nervous wreck, I hated the game. Anyway, thanks for the flashback. Nicely done.</td>', 'I hated this game -- it made me a nervous wreck. Or maybe because I was a nervous wreck, I hated the game. Anyway, thanks for the flashback. Nicely done.', '2008-05-03 00:49:23.000000', NULL, 1),
(4676329, 673308, 76335, '<td valign="top">Ha! Nicely composed. I would have cloned out the dust.</td>', 'Ha! Nicely composed. I would have cloned out the dust.', '2008-05-03 00:49:37.000000', NULL, 1),
(4676331, 672569, 76335, '<td valign="top">Nicely conceived and composed, but it looks like a case of hand shake. Use a tripod or some other steady surface in low light situations.</td>', 'Nicely conceived and composed, but it looks like a case of hand shake. Use a tripod or some other steady surface in low light situations.', '2008-05-03 00:50:24.000000', NULL, 1),
(4676333, 673122, 76335, '<td valign="top">Scrabble in the grass? Looks oversaturated.</td>', 'Scrabble in the grass? Looks oversaturated.', '2008-05-03 00:50:50.000000', NULL, 1),
(4676335, 672875, 76335, '<td valign="top">Do I see whatever''s supporting the three balls reflected in the six ball? A nice idea (if not somewhat cliche), but the lighting is way off.</td>', 'Do I see whatever''s supporting the three balls reflected in the six ball? A nice idea (if not somewhat cliche), but the lighting is way off.', '2008-05-03 00:51:24.000000', NULL, 1),
(4676336, 673504, 76335, '<td valign="top">Excellent capture. Almost looks posed -- like a game of Twister. A nine for you.</td>', 'Excellent capture. Almost looks posed -- like a game of Twister. A nine for you.', '2008-05-03 00:51:46.000000', NULL, 1),
(4676337, 673508, 76335, '<td valign="top">Excellent processing; love the colors. Nicely composed and captured also. A nine for you.</td>', 'Excellent processing; love the colors. Nicely composed and captured also. A nine for you.', '2008-05-03 00:52:00.000000', NULL, 1),
(4676338, 673222, 76335, '<td valign="top">I got a good chuckle out of this. Too bad you couldn''t use a couple dogs for the knights. But this works! An eight for you.</td>', 'I got a good chuckle out of this. Too bad you couldn''t use a couple dogs for the knights. But this works! An eight for you.', '2008-05-03 00:52:13.000000', NULL, 1),
(4676339, 673594, 76335, '<td valign="top">Excellent everything. Congrats! An eight for you.</td>', 'Excellent everything. Congrats! An eight for you.', '2008-05-03 00:52:37.000000', NULL, 1),
(4676340, 673559, 76335, '<td valign="top">Bold. I like the BW and especially the light (natural?). Nice textures and DOF also. Good work! An eight for you.</td>', 'Bold. I like the BW and especially the light (natural?). Nice textures and DOF also. Good work! An eight for you.', '2008-05-03 00:52:42.000000', NULL, 1),
(4676341, 673051, 76335, '<td valign="top">Not really a game, but try telling him that, right? It''s a great capture. A seven for you.</td>', 'Not really a game, but try telling him that, right? It''s a great capture. A seven for you.', '2008-05-03 00:53:31.000000', NULL, 1),
(4676342, 673316, 76335, '<td valign="top">Nice capture. You can feel the potential energy, the tense muscles ready to spring into action. Nice vignette too. A seven for you.</td>', 'Nice capture. You can feel the potential energy, the tense muscles ready to spring into action. Nice vignette too. A seven for you.', '2008-05-03 00:53:38.000000', NULL, 1),
(4676343, 673483, 76335, '<td valign="top">Wonderful composition. A seven for you.</td>', 'Wonderful composition. A seven for you.', '2008-05-03 00:53:55.000000', NULL, 1),
(4676344, 673545, 76335, '<td valign="top">This won''t score well, which is too bad. It''s edgy and I like it. I''d have been tempted to reduce the noise, which probably would have spoiled it. Nice work! A seven for you.</td>', 'This won''t score well, which is too bad. It''s edgy and I like it. I''d have been tempted to reduce the noise, which probably would have spoiled it. Nice work! A seven for you.', '2008-05-03 00:54:01.000000', NULL, 1),
(4676346, 673567, 76335, '<td valign="top">Somewhat cliche, but very neat what you''ve done. A seven for you.</td>', 'Somewhat cliche, but very neat what you''ve done. A seven for you.', '2008-05-03 00:54:28.000000', NULL, 1),
(4676347, 673591, 76335, '<td valign="top">Excellent candid with vibrant colors and honest emotion. Nicely done! A seven for you.</td>', 'Excellent candid with vibrant colors and honest emotion. Nicely done! A seven for you.', '2008-05-03 00:54:39.000000', NULL, 1),
(4676348, 673589, 76335, '<td valign="top">One of the better chess shots. I like the clarity, and the BW matches the nature of the game. The white spot in the foreground is a bit distracting. A seven for you.</td>', 'One of the better chess shots. I like the clarity, and the BW matches the nature of the game. The white spot in the foreground is a bit distracting. A seven for you.', '2008-05-03 00:54:48.000000', NULL, 1),
(4676349, 673590, 76335, '<td valign="top">Nice POV and the selective desat really works. A seven for you.</td>', 'Nice POV and the selective desat really works. A seven for you.', '2008-05-03 00:54:53.000000', NULL, 1),
(4676350, 673524, 76335, '<td valign="top">This is very good. A little more DOF would have been nice. A seven for you.</td>', 'This is very good. A little more DOF would have been nice. A seven for you.', '2008-05-03 00:55:01.000000', NULL, 1),
(4676353, 673540, 76335, '<td valign="top">Excellent lighting and great sharpness and clarity.</td>', 'Excellent lighting and great sharpness and clarity.', '2008-05-03 00:56:27.000000', NULL, 1),
(4676355, 673555, 76335, '<td valign="top">Great action capture. I might have cropped out more of the ump.</td>', 'Great action capture. I might have cropped out more of the ump.', '2008-05-03 00:58:23.000000', NULL, 1),
(4676358, 673326, 76335, '<td valign="top">The background is a bit unfortunate, but a nice action capture anyway.</td>', 'The background is a bit unfortunate, but a nice action capture anyway.', '2008-05-03 00:59:46.000000', NULL, 1),
(4676362, 673602, 76335, '<td valign="top">Fun shot! Nicely captured and processed.</td>', 'Fun shot! Nicely captured and processed.', '2008-05-03 01:01:04.000000', NULL, 1),
(4676598, 673591, 41337, '<td valign="top">Nicely captured!</td>', 'Nicely captured!', '2008-05-03 04:14:38.000000', NULL, 1),
(4676625, 672395, 41337, '<td valign="top">Wonderful. <br/> <br/>Returning for a bump. I love the lighting and the dust. It''s an excellent photo and as a result this gets my top vote and the YankO Blue (tied with another). Good luck!<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657188" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif"/></a></td>', 'Wonderful.  Returning for a bump. I love the lighting and the dust. It''s an excellent photo and as a result this gets my top vote and the YankO Blue (tied with another). Good luck! ', '2008-05-03 04:41:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4676626, 673508, 41337, '<td valign="top">This is a wonderfully composed shot. All those triangles within the frame strengthens and intensifies the focus and as a result produces a perfect illustration of a "pitcher". Btw, this kind of reminds me of the famous photo of <a href="//en.wikipedia.org/wiki/Eddie_Gaedel" rel="nofollow" target="_blank">Eddie Gaedel</a>, the smallest person to play professional baseball. <br/> <br/>Before I forget, let me just say this gets my YankO Red. Good luck.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657189" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657189.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657189.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657189.gif"/></a></td>', 'This is a wonderfully composed shot. All those triangles within the frame strengthens and intensifies the focus and as a result produces a perfect illustration of a "pitcher". Btw, this kind of reminds me of the famous photo of Eddie Gaedel, the smallest person to play professional baseball.  Before I forget, let me just say this gets my YankO Red. Good luck. ', '2008-05-03 04:42:14.000000', NULL, 1),
(4676630, 673590, 41337, '<td valign="top">This is such an intelligent and artistic photo. I love the play on opposites, dark/light, hidden/exposed, eyes closed/opened and there are probably more that I''m missing. Compositionally, this is also great. The child placed so high up on the frame suggest superiority, perhaps even god like superiority. The choice in having a child play that role couldn''t be any better, IMO. <br/> <br/>Ok, maybe I''m reading too much but your artistry in crafting this photo led me there. Well done. This gets my YankO Blue (along with another photo). Good Luck!<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657188" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/40000-44999/41337/120/657188.gif"/></a></td>', 'This is such an intelligent and artistic photo. I love the play on opposites, dark/light, hidden/exposed, eyes closed/opened and there are probably more that I''m missing. Compositionally, this is also great. The child placed so high up on the frame suggest superiority, perhaps even god like superiority. The choice in having a child play that role couldn''t be any better, IMO.  Ok, maybe I''m reading too much but your artistry in crafting this photo led me there. Well done. This gets my YankO Blue (along with another photo). Good Luck! ', '2008-05-03 04:43:44.000000', NULL, 1),
(4676653, 673232, 67892, '<td valign="top">cool idea</td>', 'cool idea', '2008-05-03 05:17:15.000000', NULL, 1),
(4676672, 672752, 87278, '<td valign="top">Looks simple but great!</td>', 'Looks simple but great!', '2008-05-03 06:06:16.000000', NULL, 1),
(4676678, 673597, 87278, '<td valign="top">something new, really!</td>', 'something new, really!', '2008-05-03 06:13:45.000000', NULL, 1),
(4676970, 673555, 77838, '<td valign="top">Sweet action shot.  I like being able to see the ball in the frame, too bad it''s right in the middle of #24''s head! No point loss for that though. -BB</td>', 'Sweet action shot.  I like being able to see the ball in the frame, too bad it''s right in the middle of #24''s head! No point loss for that though. -BB', '2008-05-03 11:39:11.000000', NULL, 1),
(4676972, 673444, 77838, '<td valign="top">A bit gruesome but true.</td>', 'A bit gruesome but true.', '2008-05-03 11:39:59.000000', NULL, 1),
(4676973, 673573, 77838, '<td valign="top">The post processing is really soft for me.  I like the action portrayed but the image feels like it has lost a little of it''s 3D depth. -BB</td>', 'The post processing is really soft for me.  I like the action portrayed but the image feels like it has lost a little of it''s 3D depth. -BB', '2008-05-03 11:40:15.000000', NULL, 1),
(4676981, 673597, 77838, '<td valign="top">Wow, I hope this isn''t a real thing.  Not only can sudoku''s be challenging but a rubik''s cube on top of that! Good use of 1/3s.</td>', 'Wow, I hope this isn''t a real thing.  Not only can sudoku''s be challenging but a rubik''s cube on top of that! Good use of 1/3s.', '2008-05-03 11:45:03.000000', NULL, 1),
(4676988, 673432, 77838, '<td valign="top">I like his smirk.  One little touch that might''ve turned out cool would be to allow the cards to be reflected in his glasses.  Maybe have an Ace or Pair of Kings reflected? -BB</td>', 'I like his smirk.  One little touch that might''ve turned out cool would be to allow the cards to be reflected in his glasses.  Maybe have an Ace or Pair of Kings reflected? -BB', '2008-05-03 11:47:25.000000', NULL, 1),
(4676990, 673149, 77838, '<td valign="top">The way your tiles are set up I want to read it like "Agrae mfeusn".  I wonder if you could''ve set the tiles a couple rows farther apart if we could differentiate between the words easier? -BB</td>', 'The way your tiles are set up I want to read it like "Agrae mfeusn".  I wonder if you could''ve set the tiles a couple rows farther apart if we could differentiate between the words easier? -BB', '2008-05-03 11:50:22.000000', NULL, 1),
(4676992, 673545, 77838, '<td valign="top">Feels a little too grainy and I''m a little confused as to what the chrome colored bar coming out of the right side of the frame is. -BB</td>', 'Feels a little too grainy and I''m a little confused as to what the chrome colored bar coming out of the right side of the frame is. -BB', '2008-05-03 11:52:14.000000', NULL, 1),
(4676995, 673252, 77838, '<td valign="top">I like her expression.  It''s a classic! lol.  Your overall coloring feels a little soft.  The colors could be a little brighter to help emphasize the "children" here. -BB</td>', 'I like her expression.  It''s a classic! lol.  Your overall coloring feels a little soft.  The colors could be a little brighter to help emphasize the "children" here. -BB', '2008-05-03 11:55:00.000000', NULL, 1),
(4676997, 673264, 77838, '<td valign="top">With only the pawn in focus the overall image feels really fuzzy and all of the pieces feel like they are leaning a little to the right. -BB</td>', 'With only the pawn in focus the overall image feels really fuzzy and all of the pieces feel like they are leaning a little to the right. -BB', '2008-05-03 11:56:39.000000', NULL, 1),
(4677009, 673310, 77838, '<td valign="top">Kites are GOOD!  Your''s is a little bigger than mine.  I like seeing the other kites in the background also.  They''re a little distracting but in a good way.  <br/> <br/>My eyes follow the string from the top right down to the lower left.  Then can go up to the three above and lastly to complete a figure 8 in the image to end up on the little blue kite in the lower right-hand corner. Nicely done -BB</td>', 'Kites are GOOD!  Your''s is a little bigger than mine.  I like seeing the other kites in the background also.  They''re a little distracting but in a good way.   My eyes follow the string from the top right down to the lower left.  Then can go up to the three above and lastly to complete a figure 8 in the image to end up on the little blue kite in the lower right-hand corner. Nicely done -BB', '2008-05-03 12:02:05.000000', NULL, 1),
(4677013, 673473, 77838, '<td valign="top">Perfect; this could be a long game though!  The green background is complimentary with the lighter color of the woodys. -BB</td>', 'Perfect; this could be a long game though!  The green background is complimentary with the lighter color of the woodys. -BB', '2008-05-03 12:04:30.000000', NULL, 1),
