(4680599, 671894, 12661, '<td valign="top">LOL. This photo came up just after another photo of a player running for home. I just left that one a comment that if the ball was in the frame, it would have scored bonus points. I voted, and your image came up. Ask and you shall see.<br/> <br/>As far as your photo, I like the composition. A nice clean background really helps the subject pop out of the image. The eye contact of the runner to the ball helps the viewer shift his attention appropriately. The noise is a bit annoying, I''m guessing a result of a high ISO to allow for a fast shutter speed. Not much to do about that short of spending thousands of dollars on fast zoom lenses.</td>', 'LOL. This photo came up just after another photo of a player running for home. I just left that one a comment that if the ball was in the frame, it would have scored bonus points. I voted, and your image came up. Ask and you shall see. As far as your photo, I like the composition. A nice clean background really helps the subject pop out of the image. The eye contact of the runner to the ball helps the viewer shift his attention appropriately. The noise is a bit annoying, I''m guessing a result of a high ISO to allow for a fast shutter speed. Not much to do about that short of spending thousands of dollars on fast zoom lenses.', '2008-05-05 01:19:17.000000', NULL, 0),
(4680907, 673559, 90495, '<td valign="top">You were playing alone? I would have liked to have seen the two other pegs, or at least one. Good shot.</td>', 'You were playing alone? I would have liked to have seen the two other pegs, or at least one. Good shot.', '2008-05-05 04:40:48.000000', NULL, 0),
(4680908, 673166, 90495, '<td valign="top">The tilt of the table didn''t help this image. Great idea and execution.</td>', 'The tilt of the table didn''t help this image. Great idea and execution.', '2008-05-05 04:42:20.000000', NULL, 0),
(4680977, 673566, 20608, '<td valign="top">Marvelous mate, very tidy indeed.</td>', 'Marvelous mate, very tidy indeed.', '2008-05-05 07:51:39.000000', NULL, 0),
(4680978, 673504, 20608, '<td valign="top">OUCH! that''s a ''ball game'' you can keep.</td>', 'OUCH! that''s a ''ball game'' you can keep.', '2008-05-05 07:52:29.000000', NULL, 0),
(4680979, 673350, 18450, '<td valign="top">Beautiful tones and composition! Congrats on the red Irene!!!</td>', 'Beautiful tones and composition! Congrats on the red Irene!!!', '2008-05-05 07:53:32.000000', NULL, 0),
(4680982, 673510, 62357, '<td valign="top">Oh that''s cute.</td>', 'Oh that''s cute.', '2008-05-05 07:54:25.000000', NULL, 0),
