(4681006, 673350, 28742, '<td valign="top">Apparently not too boring. ;-) You ribboned without even a splash! :) Congrats!</td>', 'Apparently not too boring. ;-) You ribboned without even a splash! :) Congrats!', '2008-05-05 08:06:48.000000', NULL, 0),
(4681007, 673573, 62187, '<td valign="top">Hi Jason,<br/> <br/>I''ve not participated much lately at DPC and I''m sorry I didn''t vote in this challenge. I picked your photo as my Blue Ribbon. I thought most of the other entries were ''snap-shot-ish'' and too much ''in the box''. You took advantage of the ''Expert'' edit to create something different AND your subjects of the photo made a person have to use that...ummm...what do you call it? Oh, Brain! Hmmm...no wonder...people need to look past the obvious - something painfully difficult I think these days. Anyway - great work. I really like it. The focus is excellent and the title is trophy!</td>', 'Hi Jason, I''ve not participated much lately at DPC and I''m sorry I didn''t vote in this challenge. I picked your photo as my Blue Ribbon. I thought most of the other entries were ''snap-shot-ish'' and too much ''in the box''. You took advantage of the ''Expert'' edit to create something different AND your subjects of the photo made a person have to use that...ummm...what do you call it? Oh, Brain! Hmmm...no wonder...people need to look past the obvious - something painfully difficult I think these days. Anyway - great work. I really like it. The focus is excellent and the title is trophy!', '2008-05-05 08:07:00.000000', NULL, 0),
(4681010, 672395, 46177, '<td valign="top">Congratulations, I gave this one a 10, just loved it!</td>', 'Congratulations, I gave this one a 10, just loved it!', '2008-05-05 08:08:40.000000', NULL, 0),
